INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('019f9ebf-c0e1-7e17-b0f4-c94a7c857d61'::uuid, '019f9df7-a2a0-71cf-9863-4d6d67e42e6d'::uuid, 'The green and red lights flash every 6 seconds and 8 seconds respectively. If they start together, how long will it take for them to next flash simultaneously?', '24 s', 'Find the least common multiple of 6 and 8. LCM(6, 8) = 24, so they will next flash together after 24 seconds.', 'Easy', '{"tags":"numbers,lcm,time","subtopic":"lcm","question_type":"open-ended","diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-26T14:06:34.721Z'::timestamptz, '2026-07-26T14:06:34.721Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('019f9ebf-c0e5-7b31-b834-96bab2ec6168'::uuid, '019f9df7-a2a0-71cf-9863-4d6d67e42e6d'::uuid, 'Express 2250 as a product of its prime factors.', '2 × 3^2 × 5^3', '2250 = 225 × 10 = (3^2 × 5^2) × (2 × 5) = 2 × 3^2 × 5^3.', 'Easy', '{"tags":"numbers,prime-factorisation","subtopic":"prime factorisation","question_type":"open-ended","diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-26T14:06:34.725Z'::timestamptz, '2026-07-26T14:06:34.725Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('019f9ebf-c0e9-779f-87dc-0cfb78d5ac8a'::uuid, '019f9df7-a2a2-77cc-bb88-40ce254805a8'::uuid, 'The period P of a pendulum is directly proportional to the square root of its length L. If P increases by 25%, what is the percentage increase in L?', '56.25%', 'Since P is proportional to sqrt(L), L is proportional to P^2. If P increases by 25%, then L changes by 1.25^2 = 1.5625. So the increase in L is 56.25%.', 'Medium', '{"tags":"ratio,proportion,percentage-change","subtopic":"direct proportion","question_type":"open-ended","diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-26T14:06:34.729Z'::timestamptz, '2026-07-26T14:06:34.729Z'::timestamptz) ON CONFLICT (id) DO NOTHING;